"""
运维记录处理库 (Ops Record Processing Library)
包含30个小型纯函数，覆盖排序、筛选、金额汇总和字段校验。
"""

def sort_by_latency(records: list[dict]) -> list[dict]:
    """按延迟时间升序排序记录。"""
    return sorted(records, key=lambda x: x.get('latency_ms', 0))


def sort_by_shard(records: list[dict]) -> list[dict]:
    """按分片ID升序排序记录。"""
    return sorted(records, key=lambda x: x.get('shard', 0))


def sort_by_event_id(records: list[dict]) -> list[dict]:
    """按事件ID字符串升序排序记录。"""
    return sorted(records, key=lambda x: x.get('id', ''))


def filter_by_shard(records: list[dict], shard_id: int) -> list[dict]:
    """筛选指定分片的记录。"""
    return [r for r in records if r.get('shard') == shard_id]


def filter_by_state(records: list[dict], state: str) -> list[dict]:
    """筛选指定状态的记录。"""
    return [r for r in records if r.get('state') == state]


def filter_high_latency(records: list[dict], threshold_ms: int) -> list[dict]:
    """筛选延迟高于阈值的记录。"""
    return [r for r in records if r.get('latency_ms', 0) > threshold_ms]


def filter_low_latency(records: list[dict], threshold_ms: int) -> list[dict]:
    """筛选延迟低于阈值的记录。"""
    return [r for r in records if r.get('latency_ms', 0) < threshold_ms]


def sum_latency(records: list[dict]) -> int:
    """汇总所有记录的延迟总和。"""
    return sum(r.get('latency_ms', 0) for r in records)


def avg_latency(records: list[dict]) -> float:
    """计算平均延迟。"""
    if not records:
        return 0.0
    return sum_latency(records) / len(records)


def max_latency(records: list[dict]) -> int:
    """获取最大延迟值。"""
    if not records:
        return 0
